import json,sys
S,out=sys.argv[1],sys.argv[2]
cap=json.load(open(f'{S}/tools/captions.json')); exp=json.load(open(f'{S}/tools/exported.json'))
L=['/**',' * Photo albums from the Foundation\'s own photographs (Google Drive export of its Facebook albums).',' * Each album is matched to the Foundation\'s Facebook post (source of record) and to a Story of Impact.',' * Photos showing identifiable vulnerable people in sensitive situations were left out: see docs/media-gallery-report.md.',' * Generated by scripts/gallery (captions reviewed by hand).',' */','import type { PillarKey, StorySlug } from "./platform";','','export type GalleryPhoto = { src: string; w: number; h: number; caption: { en: string; fr: string } };','export type Album = { slug: StorySlug; category: PillarKey; credit: string; source: { label: string; url: string }; cover: number; photos: GalleryPhoto[] };','','export const albums: Album[] = [']
for slug,a in cap.items():
    ph=exp[slug]; assert len(ph)==len(a['c']),slug
    L.append(f'  {{ slug: "{slug}", category: "{a["category"]}", credit: {json.dumps(a["credit"])}, source: {{ label: {json.dumps(a["source"][0])}, url: "{a["source"][1]}" }}, cover: {a["cover"]-1}, photos: [')
    for p,(en,fr) in zip(ph,a['c']):
        L.append(f'    {{ src: "{p["file"]}", w: {p["w"]}, h: {p["h"]}, caption: {{ en: {json.dumps(en,ensure_ascii=False)}, fr: {json.dumps(fr,ensure_ascii=False)} }} }},')
    L.append('  ] },')
L+=['];','','export const albumFor = (slug: string) => albums.find((a) => a.slug === slug);','export const albumCover = (a: Album) => a.photos[a.cover];','']
open(out,'w').write('\n'.join(L))
